solution.hangman.zig:
const std = @import("std");

pub const Status = enum { ongoing, win, lose };
pub const Hangman = struct {
    word: []const u8,
    guessed: [256]bool = @splat(false),
    remaining_guesses: i8 = 9,
    status: Status = .ongoing,
    pub fn init(word: []const u8) Hangman { return .{.word=word}; }
    pub fn guess(self: *Hangman, character: u8) !void {
        if (self.status != .ongoing) return error.GameAlreadyEnded;
        if (self.guessed[character] or std.mem.indexOfScalar(u8,self.word,character) == null) self.remaining_guesses -= 1 else self.guessed[character] = true;
        var won = true;
        for (self.word) |c| if (!self.guessed[c]) { won=false; break; };
        self.status = if (won) .win else if (self.remaining_guesses < 0) .lose else .ongoing;
    }
    pub fn maskedWord(self: Hangman, allocator: std.mem.Allocator) ![]u8 {
        const mask = try allocator.alloc(u8,self.word.len);
        for (self.word,0..) |c,i| mask[i] = if (self.guessed[c]) c else '_';
        return mask;
    }
};

tests.test_hangman.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("hangman.zig");

test "correct, incorrect and repeated guesses; win and loss" {
    var game = m.Hangman.init("banana");
    const initial = try game.maskedWord(a); defer a.free(initial); try t.expectEqualStrings("______",initial);
    try game.guess('a'); const mask = try game.maskedWord(a); defer a.free(mask); try t.expectEqualStrings("_a_a_a",mask);
    try t.expectEqual(@as(i8,9),game.remaining_guesses);
    try game.guess('a'); try game.guess('z'); try game.guess('z'); try t.expectEqual(@as(i8,6),game.remaining_guesses);
    try game.guess('b'); try game.guess('n'); try t.expectEqual(m.Status.win,game.status);
    try t.expectError(error.GameAlreadyEnded,game.guess('a'));
    var lost = m.Hangman.init("cat");
    for (0..9) |_| try lost.guess('x');
    try t.expectEqual(m.Status.ongoing,lost.status); try t.expectEqual(@as(i8,0),lost.remaining_guesses);
    try lost.guess('x'); try t.expectEqual(m.Status.lose,lost.status);
    try t.expectError(error.GameAlreadyEnded,lost.guess('c'));
}
